import{_ as r}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as a,o as e,af as l}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const u=JSON.parse('{"title":"智谱清言 / Z.ai 对话","description":"写给谁：要在浏览器或官方 App 里用智谱助手的前端工程师。不需要仓库。","frontmatter":{"title":"智谱清言 / Z.ai 对话","description":"写给谁：要在浏览器或官方 App 里用智谱助手的前端工程师。不需要仓库。","domain":"product","tags":["coding-agent"],"role":"tutorial"},"headers":[],"relativePath":"zh/products/zhipu-chat/zhipu-chat.md","filePath":"zh/products/zhipu-chat/zhipu-chat.md","lastUpdated":1787110548000}'),n={name:"zh/products/zhipu-chat/zhipu-chat.md"};function o(h,t,d,i,s,c){return e(),a("div",null,[...t[0]||(t[0]=[l('<h1 id="智谱清言-z-ai-对话" tabindex="-1">智谱清言 / Z.ai 对话 <a class="header-anchor" href="#智谱清言-z-ai-对话" aria-label="Permalink to &quot;智谱清言 / Z.ai 对话&quot;">​</a></h1><blockquote><p>本页只根据官方产品页、付费协议、商店页和模型公告画对话面。对位 Claude.ai。</p><p>它<strong>不是</strong> GLM Coding Plan，也不是 ZCode。编码套餐见 <a href="./">学习地图</a> 那一行。</p></blockquote><h2 id="目标与非目标" tabindex="-1">目标与非目标 <a class="header-anchor" href="#目标与非目标" aria-label="Permalink to &quot;目标与非目标&quot;">​</a></h2><p><strong>写给谁：</strong> 前端工程师。你需要浏览器或清言 App。</p><p><strong>目标：</strong> 写清两个官方对话入口实际是什么、能做什么、账号和付费边界在哪。</p><p><strong>非目标：</strong> Coding Plan 安装、API SDK、臆造每日次数 / token 上限 / 现行会员价、模型内部（链 <a href="/zh/tech/fundamentals/LLM.html">Learn LLM</a>）。</p><h2 id="先决条件" tabindex="-1">先决条件 <a class="header-anchor" href="#先决条件" aria-label="Permalink to &quot;先决条件&quot;">​</a></h2><ul><li>能打开 <a href="https://chatglm.cn" target="_blank" rel="noreferrer">chatglm.cn</a> 或 <a href="https://chat.z.ai" target="_blank" rel="noreferrer">chat.z.ai</a></li><li>国内面准备手机号 / 微信等清言支持的登录方式；国际面按 Z.ai 登录页为准</li><li>不需要 Git 仓库、不需要 API Key</li></ul><h2 id="学习目标" tabindex="-1">学习目标 <a class="header-anchor" href="#学习目标" aria-label="Permalink to &quot;学习目标&quot;">​</a></h2><ul><li>能选对「清言」还是「Z.ai」</li><li>能发出第一条对话，并认出官方能力芯片</li><li>知道会员权益绑在哪个账号上，以及为什么不能拿开放平台额度当清言会员</li></ul><h2 id="它是什么" tabindex="-1">它是什么 <a class="header-anchor" href="#它是什么" aria-label="Permalink to &quot;它是什么&quot;">​</a></h2><p>一张对话面，两个官方入口。官方「在线体验」原文（<a href="https://www.zhipuai.cn/zh/research/161" target="_blank" rel="noreferrer">GLM-5.2 研究页</a>）：</p><table tabindex="0"><thead><tr><th>入口</th><th>官方写法</th><th>URL</th></tr></thead><tbody><tr><td>国内</td><td>智谱清言 App/网页版</td><td><a href="https://chatglm.cn" target="_blank" rel="noreferrer">chatglm.cn</a></td></tr><tr><td>国际</td><td>Z.ai</td><td><a href="https://chat.z.ai" target="_blank" rel="noreferrer">chat.z.ai</a></td></tr></tbody></table><p>客户端（只写官方写过的）：</p><table tabindex="0"><thead><tr><th>客户端</th><th>依据</th></tr></thead><tbody><tr><td>网页</td><td><a href="https://chatglm.cn" target="_blank" rel="noreferrer">chatglm.cn</a>、<a href="https://chat.z.ai" target="_blank" rel="noreferrer">chat.z.ai</a></td></tr><tr><td>官方 App</td><td><a href="https://chatglm.cn/download" target="_blank" rel="noreferrer">chatglm.cn/download</a>；App Store <a href="https://apps.apple.com/cn/app/id6450893458" target="_blank" rel="noreferrer">智谱清言</a></td></tr><tr><td>浏览器插件</td><td>Chrome Web Store「智谱清言：ChatGLM &amp; AutoGLM」</td></tr></tbody></table><p>这些页面上<strong>没有</strong>「把清言装成仓库 CLI」的官方步骤。对话里写代码仍是聊天，不是 checkout Agent。</p><h2 id="智谱清言-打开就能聊" tabindex="-1">智谱清言：打开就能聊 <a class="header-anchor" href="#智谱清言-打开就能聊" aria-label="Permalink to &quot;智谱清言：打开就能聊&quot;">​</a></h2><ol><li>打开 <a href="https://chatglm.cn" target="_blank" rel="noreferrer">chatglm.cn</a>。</li><li>登录。付费协议把服务范围写成 <strong>chatglm.cn 网站、智谱清言 App</strong>（<a href="https://chatglm.cn/pay/policy/vipservice" target="_blank" rel="noreferrer">付费服务协议</a> §1.5）。</li><li>在输入框发问题。页脚要求你读 <a href="https://chatglm.cn/agreement" target="_blank" rel="noreferrer">用户协议</a> 与 <a href="https://chatglm.cn/privacypolicy" target="_blank" rel="noreferrer">隐私政策</a>。</li></ol><p>2026-08-19 首页可见的入口芯片：</p><table tabindex="0"><thead><tr><th>芯片</th><th>只说明「官方把这件事放在首页」</th></tr></thead><tbody><tr><td><strong>Agent</strong></td><td>首页定位就是「能帮你把事办成的 Agent」</td></tr><tr><td><strong>研究报告</strong></td><td>官方首页入口</td></tr><tr><td><strong>PPT制作</strong></td><td>官方首页入口</td></tr><tr><td><strong>数据分析</strong></td><td>官方首页入口</td></tr><tr><td><strong>GLM-5.2 / GLM-5.2快速</strong></td><td>页面上的模型名；以你账号里实际能选的为准</td></tr></tbody></table><p>下载页补充的能力（<a href="https://chatglm.cn/download" target="_blank" rel="noreferrer">chatglm.cn/download</a>）：对话、写作、编程、理解图片与文档；「可以对话聊天、也可以调用工具执行复杂任务」。</p><p>付费协议列出的权益<strong>种类</strong>（§1.6、§4.1，不是额度数字）：</p><ul><li>各模型相关权益</li><li>各类型 Agent 权益</li><li>清影生视频</li><li>视频通话</li><li>更大的云知识库空间</li><li>更多 AI 画图功能</li></ul><p><strong>具体次数、积分、是否仍叫 VIP/SVIP，以登录后的会员权益页为准。</strong> 协议允许智谱改权益和价格，并要求你看服务页最新展示。</p><p>App Store 官方介绍还按场景写了通用问答、写作、学习、职场、编程、虚拟对话等。那是商店文案，用来理解产品面，不要当成命令清单。</p><h3 id="浏览器插件" tabindex="-1">浏览器插件 <a class="header-anchor" href="#浏览器插件" aria-label="Permalink to &quot;浏览器插件&quot;">​</a></h3><p>官方插件名：<strong>智谱清言：ChatGLM &amp; AutoGLM</strong>（Chrome Web Store，开发者标识 zhipuextension）。商店原文能力：通用问答侧边栏、页面总结、页面对话、划线解释/总结/翻译、写作助手、勾选总结、站内高级检索。插件政策见 <a href="https://chatglm.cn/advanced-authpolicy" target="_blank" rel="noreferrer">chatglm.cn/advanced-authpolicy</a>。</p><h2 id="z-ai-国际对话面" tabindex="-1">Z.ai：国际对话面 <a class="header-anchor" href="#z-ai-国际对话面" aria-label="Permalink to &quot;Z.ai：国际对话面&quot;">​</a></h2><ol><li>打开 <a href="https://chat.z.ai" target="_blank" rel="noreferrer">chat.z.ai</a> 或顶栏带 <strong>Chat</strong> 的 <a href="https://z.ai" target="_blank" rel="noreferrer">z.ai</a>。</li><li>按页面登录。Z.ai 顶栏同时有 <strong>Chat / API / Coding Plan / Contact / Docs</strong>（<a href="https://z.ai/company" target="_blank" rel="noreferrer">z.ai/company</a>）。<strong>Chat</strong> 才是本页；<strong>Coding Plan</strong> 和 <strong>Docs</strong> 不是清言教程。</li></ol><p>官方对自己的定义（页面 description）：</p><blockquote><p>Meet Z.ai, the AI assistant powered by GLM-5.2. Build websites, write code, handle long-horizon tasks, and get instant answers.</p></blockquote><p>2026-08-19 页面可见芯片：<strong>Magic Design</strong>、<strong>Full-Stack</strong>、<strong>Write Code</strong>。</p><p>官方 blog 对聊天面的补充（只抄原文能撑住的）：</p><ul><li><a href="https://z.ai/blog/glm-4.5" target="_blank" rel="noreferrer">glm-4.5</a>：在 Z.ai 选模型即可聊；支持 artifacts、presentation slide、full-stack development。</li><li><a href="https://z.ai/blog/glm-5.2" target="_blank" rel="noreferrer">glm-5.2</a>：「Chat with GLM-5.2 on Z.ai」。同一篇把 Coding Plan / ZCode 写成另一条路径。</li></ul><p>Z.ai 的法律文本在 <a href="https://docs.z.ai/legal-agreement/terms-of-use" target="_blank" rel="noreferrer">Terms of Use</a>（签约方 JINGSHENG HENGXING TECHNOLOGY PTE.LTD）。那份条款主要覆盖平台 / API 使用，<strong>不要</strong>用它反推清言国内会员规则。</p><h2 id="账号与付费-只写协议原文" tabindex="-1">账号与付费（只写协议原文） <a class="header-anchor" href="#账号与付费-只写协议原文" aria-label="Permalink to &quot;账号与付费（只写协议原文）&quot;">​</a></h2><p>清言付费协议（生效 2026-05-21）里，前端工程师最容易踩的几条：</p><table tabindex="0"><thead><tr><th>规则</th><th>原文要点</th></tr></thead><tbody><tr><td>权益跟账号走</td><td>多个清言账号时，权益只进<strong>购买时登录的那个</strong>。账号之间充值 / 会员<strong>不能</strong>转移、迁徙、转让、分享（§3.1、§3.2.2）</td></tr><tr><td>和开放平台不是同一份</td><td>清言会员与智谱其它产品（「包括但不限于智谱 AI 开放平台」）付费<strong>独立不冲突</strong>，重合权益可叠加，<strong>不会</strong>因此退款（§4.4）</td></tr><tr><td>价格看页面</td><td>收费标准、优惠、付款方式会改；以服务页公示为准（§4.7）</td></tr><tr><td>默认不退</td><td>付费服务不能退货退款、换货、兑现金；重复扣款或官方技术故障导致无法履约，走客服申诉（§4.5、§4.8.1）</td></tr><tr><td>设备会不一样</td><td>软件版本、设备、操作系统不同，实际能用的服务可能有差别（§4.6）</td></tr></tbody></table><p>App Store 列出过内购档位（连续包月、月卡、清影智能体等）。<strong>档位和价格会变</strong>，不要把某一天的截图当价目表。查 <a href="https://apps.apple.com/cn/app/id6450893458" target="_blank" rel="noreferrer">App Store 产品页</a> 或清言会员页。</p><p><strong>不要假设</strong> 清言会员 = Z.ai 登录 = Coding Plan 额度。官方没有这样写。</p><h2 id="旁边那些面-别混" tabindex="-1">旁边那些面（别混） <a class="header-anchor" href="#旁边那些面-别混" aria-label="Permalink to &quot;旁边那些面（别混）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>产品面</th><th>是什么</th><th>去哪</th></tr></thead><tbody><tr><td><strong>智谱清言 / Z.ai 对话</strong></td><td>本页</td><td>chatglm.cn / chat.z.ai</td></tr><tr><td><strong>GLM Coding Plan</strong></td><td>给编码工具的订阅</td><td><a href="https://z.ai/subscribe" target="_blank" rel="noreferrer">z.ai/subscribe</a> — 本目录不写安装</td></tr><tr><td><strong>ZCode</strong></td><td>官方代码工具</td><td><a href="https://zcode.z.ai/cn" target="_blank" rel="noreferrer">zcode.z.ai/cn</a></td></tr><tr><td><strong>AutoGLM / AutoClaw</strong></td><td>报告助手 / 本地客户端</td><td><a href="https://autoglm.zhipuai.cn" target="_blank" rel="noreferrer">autoglm.zhipuai.cn</a></td></tr><tr><td><strong>API</strong></td><td>模型 HTTP 接口</td><td><a href="https://docs.z.ai" target="_blank" rel="noreferrer">docs.z.ai</a>、<a href="https://docs.bigmodel.cn" target="_blank" rel="noreferrer">docs.bigmodel.cn</a></td></tr></tbody></table><h2 id="常见陷阱" tabindex="-1">常见陷阱 <a class="header-anchor" href="#常见陷阱" aria-label="Permalink to &quot;常见陷阱&quot;">​</a></h2><ul><li>打开 <a href="https://z.ai/subscribe" target="_blank" rel="noreferrer">z.ai/subscribe</a> 或 <a href="https://bigmodel.cn/glm-coding" target="_blank" rel="noreferrer">bigmodel.cn/glm-coding</a>，却以为在配置清言网页。</li><li>用 A 账号买会员、用 B 账号登录网页，然后以为「丢了订阅」。协议写明权益不搬家。</li><li>把开放平台 / Coding Plan 余额当成清言次数。协议写明两套付费独立。</li><li>把对话里生成的 HTML / 脚本当成已经改好了你的 Git 仓库。</li><li>把三方博客的「每日 50 次 / 某月 ¥xx」写进自己的笔记当官方规格。</li></ul><h2 id="官方文档" tabindex="-1">官方文档 <a class="header-anchor" href="#官方文档" aria-label="Permalink to &quot;官方文档&quot;">​</a></h2><table tabindex="0"><thead><tr><th>页面</th><th>用来干什么</th></tr></thead><tbody><tr><td><a href="https://chatglm.cn" target="_blank" rel="noreferrer">chatglm.cn</a></td><td>清言产品</td></tr><tr><td><a href="https://chatglm.cn/download" target="_blank" rel="noreferrer">chatglm.cn/download</a></td><td>App / 客户端入口</td></tr><tr><td><a href="https://chatglm.cn/pay/policy/vipservice" target="_blank" rel="noreferrer">付费服务协议</a></td><td>会员、积分、账号边界</td></tr><tr><td><a href="https://chat.z.ai" target="_blank" rel="noreferrer">chat.z.ai</a></td><td>Z.ai 对话</td></tr><tr><td><a href="https://z.ai" target="_blank" rel="noreferrer">z.ai</a></td><td>国际站顶栏（Chat / API / Coding Plan）</td></tr><tr><td><a href="https://www.zhipuai.cn/zh" target="_blank" rel="noreferrer">zhipuai.cn/zh</a></td><td>厂商一级产品</td></tr><tr><td><a href="https://www.zhipuai.cn/zh/research/161" target="_blank" rel="noreferrer">GLM-5.2 研究页</a></td><td>官方「在线体验」两个 URL</td></tr><tr><td><a href="https://docs.z.ai" target="_blank" rel="noreferrer">docs.z.ai</a></td><td>API，不是清言 How-to</td></tr></tbody></table><h2 id="相关页面" tabindex="-1">相关页面 <a class="header-anchor" href="#相关页面" aria-label="Permalink to &quot;相关页面&quot;">​</a></h2><ul><li><a href="./">学习地图</a></li><li><a href="./zhipu-chat-cheatsheet.html">速查表</a></li><li><a href="./zhipu-chat-glossary.html">术语表</a></li></ul>',48)])])}const m=r(n,[["render",o]]);export{u as __pageData,m as default};
